INSERT INTO `ld_autotaskquery` VALUES (4,'\r\nDROP PROCEDURE IF EXISTS `task_contact_birthday_reminds`; \r\ndelimiter $$ \r\nCREATE PROCEDURE `task_contact_birthday_reminds`( \r\n) \r\nBEGIN \r\nDECLARE done int DEFAULT 0; \r\nDECLARE task_crmid int default 0; \r\nDECLARE task_name varchar(200) default \'\'; \r\nDECLARE task_user int default 0; \r\nDECLARE task_time datetime DEFAULT NOW(); \r\nDECLARE mycursor cursor for SELECT contactid,lastname,smownerid FROM ld_contactdetails WHERE deleted = 0 AND birthday != \'\' AND \r\n(DATE_FORMAT(birthday,\'%m%d\') - DATE_FORMAT(CURDATE(),\'%m%d\') = 0) ORDER BY contactid; \r\nDECLARE CONTINUE HANDLER for not found set done = 1; \r\nOPEN mycursor; \r\nfetch mycursor into task_crmid,task_name,task_user; \r\nLOOP1: WHILE done != 1 DO \r\nIF task_crmid > 0 THEN \r\nset @maxid = 0; \r\nselect max(crmid) into @maxid from ld_crmentity; \r\ninsert into ld_crmentity(crmid,setype) \r\nselect @maxid+1,\'Reminds\'; \r\ninsert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted) \r\nselect @maxid+1,concat(\'计划任务：联系人生日自动提醒已执行，今天是联系人：\',task_name,\'的生日，请送上生日的祝福。\'),task_time,task_user,\'未读\',task_crmid,\'Contacts\',0,0,0,1,1,1,task_time,task_time,\'\',0; \r\nEND IF; \r\nFETCH mycursor INTO task_crmid,task_name,task_user; \r\nEND WHILE LOOP1; \r\nclose mycursor; \r\nEND $$\r\ndelimiter;\r\ncall `task_contact_birthday_reminds`();\r\ndelimiter;\r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity); \r\ndelimiter;'),(5,'DROP PROCEDURE IF EXISTS `task_pubaccout`;\r\ndelimiter $$\r\nCREATE  PROCEDURE `task_pubaccout`(\r\n)\r\nBEGIN\r\n     declare tmp_accountid  int default 0;\r\n     declare tmp_accountname varchar(200) default \'\';\r\n     declare tmp_smownerid  int default 0;\r\n		 declare tmp_allocatedate date default NULL;\r\n     declare mycursor cursor for select accountid, accountname,smownerid,allocatedate from ld_account where publicaccount in (2,3) and TIMESTAMPDIFF(DAY,allocatedate,CURDATE())>10;\r\n     DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n     open mycursor;\r\n		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_allocatedate;\r\n				while(tmp_accountid is not null) DO\r\n						IF TIMESTAMPDIFF(DAY,tmp_allocatedate,CURDATE())<30 then  \r\n								select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_allocatedate and DATE_ADD(tmp_allocatedate,INTERVAL 10 day));\r\n								IF @cn1<1 then \r\n										update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n										set @maxid=0;\r\n										select max(crmid) into @maxid from ld_crmentity;\r\n										insert into ld_crmentity(crmid,setype)\r\n										select @maxid+1,\'Reminds\';\r\n										\r\n										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n										select @maxid+1,concat(\'领取10天未增加联系记录客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n									 \r\n										insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n										select \'系统管理员\',\'领取10天未增加联系记录客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							ELSEIF TIMESTAMPDIFF(DAY,tmp_allocatedate,CURDATE())>=30 and TIMESTAMPDIFF(DAY,tmp_allocatedate,CURDATE())<=90 then\r\n									select count(1) into @cn2 from ld_potential where accountid=tmp_accountid and (createdtime between tmp_allocatedate and DATE_ADD(tmp_allocatedate,INTERVAL 30 day));\r\n									IF @cn2<1 then \r\n											update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n											set @maxid=0;\r\n											select max(crmid) into @maxid from ld_crmentity;\r\n											insert into ld_crmentity(crmid,setype)\r\n											select @maxid+1,\'Reminds\';\r\n											\r\n											insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n											select @maxid+1,concat(\'领取30天未增加销售机会客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n										 \r\n											insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n											select \'系统管理员\',\'领取30天未增加销售机会客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							ELSEIF TIMESTAMPDIFF(DAY,tmp_allocatedate,CURDATE())>90	 THEN\r\n									select count(1) into @cn3 from ld_potential where accountid=tmp_accountid and (createdtime between tmp_allocatedate and DATE_ADD(tmp_allocatedate,INTERVAL 90 day)) and sales_stage=\'成功结案\';\r\n									IF @cn3<1 then \r\n											update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n											set @maxid=0;\r\n											select max(crmid) into @maxid from ld_crmentity;\r\n											insert into ld_crmentity(crmid,setype)\r\n											select @maxid+1,\'Reminds\';\r\n											\r\n											insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n											select @maxid+1,concat(\'领取90天销售机会未成交客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n										 \r\n											insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n											select \'系统管理员\',\'领取90天销售机会未成交客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							END IF; \r\n				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_allocatedate;\r\n				end while;\r\n     close mycursor;\r\nEND $$\r\ndelimiter;\r\ncall task_pubaccout;\r\ndelimiter;\r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\ndelimiter;'),(6,'DROP PROCEDURE IF EXISTS `task_accout90`;\r\ndelimiter $$\r\nCREATE  PROCEDURE `task_accout90`(\r\n)\r\nBEGIN\r\n     declare tmp_accountid  int default 0;\r\n     declare tmp_accountname varchar(200) default \'\';\r\n     declare tmp_smownerid  int default 0;\r\n		 declare tmp_lastorderdate date default NULL;\r\n     declare mycursor cursor for select accountid, accountname,smownerid,lastorderdate from ld_account where publicaccount in (0,2,3) and TIMESTAMPDIFF(DAY,lastorderdate,CURDATE())>90;\r\n     DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n     open mycursor;\r\n		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_lastorderdate;\r\n				while(tmp_accountid is not null) DO\r\n						select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_lastorderdate and DATE_ADD(tmp_lastorderdate,INTERVAL 90 day));\r\n								IF @cn1<1 then \r\n										update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n										set @maxid=0;\r\n										select max(crmid) into @maxid from ld_crmentity;\r\n										insert into ld_crmentity(crmid,setype)\r\n										select @maxid+1,\'Reminds\';\r\n										\r\n										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n										select @maxid+1,concat(\'成交90天无联系记录客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n									 \r\n										insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n										select \'系统管理员\',\'成交90天无联系记录客户\',NOW(),tmp_accountid;\r\n								END IF; \r\n				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_lastorderdate;\r\n				end while;\r\n     close mycursor;\r\nEND $$\r\ndelimiter;\r\ncall task_accout90();\r\ndelimiter;\r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\ndelimiter;'),(7,'DROP PROCEDURE IF EXISTS `task_pubaccout02`;\r\ndelimiter $$\r\nCREATE  PROCEDURE `task_pubaccout02`(\r\n)\r\nBEGIN\r\n     declare tmp_accountid  int default 0;\r\n     declare tmp_accountname varchar(200) default \'\';\r\n     declare tmp_smownerid  int default 0;\r\n		 declare tmp_creatdate date default NULL;\r\n     declare mycursor cursor for select accountid, accountname,smownerid,createdtime from ld_account where publicaccount=0 and createdtime>\'2015-03-05\' and TIMESTAMPDIFF(DAY,createdtime,CURDATE())>10;\r\n\r\n     DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n     open mycursor;\r\n		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_creatdate;\r\n				while(tmp_accountid is not null) DO\r\n						IF TIMESTAMPDIFF(DAY,tmp_creatdate,CURDATE())<30 then  \r\n								select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_creatdate and DATE_ADD(tmp_creatdate,INTERVAL 10 day));\r\n								IF @cn1<1 then \r\n										update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n										set @maxid=0;\r\n										select max(crmid) into @maxid from ld_crmentity;\r\n										insert into ld_crmentity(crmid,setype)\r\n										select @maxid+1,\'Reminds\';\r\n										\r\n										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n										select @maxid+1,concat(\'领取10天未增加联系记录客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n									 \r\n										insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n										select \'系统管理员\',\'领取10天未增加联系记录客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							ELSEIF TIMESTAMPDIFF(DAY,tmp_creatdate,CURDATE())>=30 and TIMESTAMPDIFF(DAY,tmp_allocatedate,CURDATE())<=90 then\r\n									select count(1) into @cn2 from ld_potential where accountid=tmp_accountid and (createdtime between tmp_creatdate and DATE_ADD(tmp_creatdate,INTERVAL 30 day));\r\n									IF @cn2<1 then \r\n											update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n											set @maxid=0;\r\n											select max(crmid) into @maxid from ld_crmentity;\r\n											insert into ld_crmentity(crmid,setype)\r\n											select @maxid+1,\'Reminds\';\r\n											\r\n											insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n											select @maxid+1,concat(\'领取30天未增加销售机会客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n										 \r\n											insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n											select \'系统管理员\',\'领取30天未增加销售机会客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							ELSEIF TIMESTAMPDIFF(DAY,tmp_creatdate,CURDATE())>90	 THEN\r\n									select count(1) into @cn3 from ld_potential where accountid=tmp_accountid and (createdtime between tmp_creatdate and DATE_ADD(tmp_creatdate,INTERVAL 90 day)) and sales_stage=\'成功结案\';\r\n									IF @cn3<1 then \r\n											update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;\r\n											set @maxid=0;\r\n											select max(crmid) into @maxid from ld_crmentity;\r\n											insert into ld_crmentity(crmid,setype)\r\n											select @maxid+1,\'Reminds\';\r\n											\r\n											insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n											select @maxid+1,concat(\'领取90天销售机会未成交客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n										 \r\n											insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n											select \'系统管理员\',\'领取90天销售机会未成交客户\',NOW(),tmp_accountid;\r\n									END IF;\r\n							END IF; \r\n				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_creatdate;\r\n				end while;\r\n     close mycursor;\r\nEND $$\r\ndelimiter;\r\ncall task_pubaccout02();\r\ndelimiter;\r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\ndelimiter;'),(8,'DROP PROCEDURE IF EXISTS `task_accoutreminds10`;\r\ndelimiter $$\r\nCREATE  PROCEDURE `task_accoutreminds10`(\r\n)\r\nBEGIN\r\n     declare tmp_accountid  int default 0;\r\n     declare tmp_accountname varchar(200) default \'\';\r\n     declare tmp_smownerid  int default 0;\r\n		 declare tmp_allocatedate date default NULL;\r\n     declare mycursor cursor for select accountid, accountname,smownerid from ld_account where publicaccount in (2,3) and (TIMESTAMPDIFF(DAY,allocatedate,CURDATE())<10 and TIMESTAMPDIFF(DAY,allocatedate,CURDATE())>=7) and lastcontactdate<allocatedate;\r\n     \r\n		 DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n     open mycursor;\r\n		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;\r\n				while(tmp_accountid is not null) DO\r\n						select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_lastorderdate and DATE_ADD(tmp_lastorderdate,INTERVAL 90 day));\r\n										set @maxid=0;\r\n										select max(crmid) into @maxid from ld_crmentity;\r\n										insert into ld_crmentity(crmid,setype)\r\n										select @maxid+1,\'Reminds\';\r\n										\r\n										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n										select @maxid+1,concat(\'客户：\',tmp_accountname,\'领取7天后仍无联系记录，请尽快创建否则将自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n									 \r\n				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;\r\n				end while;\r\n     close mycursor;\r\nEND $$\r\ndelimiter;\r\ncall task_accoutreminds10();\r\ndelimiter;\r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\ndelimiter;'),(9,'DROP PROCEDURE IF EXISTS `task_accounts_remind_lastservicedate`;\ndelimiter ||\nCREATE PROCEDURE `task_accounts_remind_lastservicedate`(\n)\nBEGIN\n\n\n	declare tmp_accountid int(19) default 0;\n	declare tmp_accountname varchar(255) default NULL;\n	declare tmp_date date default NULL;\n	declare tmp_recieverid int(19) default 0;\n	declare tmp_days int(19) default 0;\n\n	declare cur1 cursor for SELECT\n								accountid,\n								accountname,\n								lastservicedate,\n								smownerid,\n								DATEDIFF(lastservicedate,CURDATE()) AS days\n							FROM ld_account\n							WHERE deleted=0\n								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);\n\n	DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\n\n	OPEN cur1;\n	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\n	while(tmp_accountid is not null) DO\n		IF tmp_days<=-30 THEN\n			SET @remind_type=\'自动任务之服务过期提醒\';\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务过期提醒%\') THEN\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经过期\',abs(tmp_days),\'天（\',tmp_date,\'），请及时跟进！\');\n\n				set @maxid=0;\n				select max(crmid) into @maxid from ld_crmentity;\n				insert into ld_crmentity(crmid,setype)\n				select @maxid+1,\'Reminds\';\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\n\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\n			END IF;\n		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN\n			SET @remind_type=\'自动任务之服务到期提醒\';\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务到期提醒%\') THEN\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经到期（\',tmp_date,\'），请及时跟进！\');\n\n				set @maxid=0;\n				select max(crmid) into @maxid from ld_crmentity;\n				insert into ld_crmentity(crmid,setype)\n				select @maxid+1,\'Reminds\';\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\n\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\n			END IF;\n		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN\n			SET @remind_type=\'自动任务之服务即将到期提醒\';\n\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务即将到期提醒%\') THEN\n\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'还有\',abs(tmp_days),\'天（\',tmp_date,\'）即将到期，请及时跟进！\');\n				set @maxid=0;\n				select max(crmid) into @maxid from ld_crmentity;\n				insert into ld_crmentity(crmid,setype)\n				select @maxid+1,\'Reminds\';\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\n\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\n			END IF;\n		END IF;\n\n		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\n	end while;\n	close cur1;\n\n\nend ||\ndelimiter;\n\nCALL task_accounts_remind_lastservicedate();\ndelimiter;'),(10,'DROP PROCEDURE IF EXISTS `task_servicecharge_remind_lastservicedate`;\ndelimiter ||\nCREATE PROCEDURE `task_servicecharge_remind_lastservicedate`(\n)\nBEGIN\n\n\n	declare tmp_accountid int(19) default 0;\n	declare tmp_accountname varchar(255) default NULL;\n	declare tmp_date date default NULL;\n	declare tmp_recieverid int(19) default 0;\n	declare tmp_days int(19) default 0;\n\n	declare cur1 cursor for SELECT\n								accountid,\n								accountname,\n								lastservicedate,\n								CASE WHEN servicecasher>0 THEN servicecasher ELSE 1 END AS servicecasher,\n								DATEDIFF(lastservicedate,CURDATE()) AS days\n							FROM ld_account\n							WHERE deleted=0\n								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);\n\n	DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\n\n	OPEN cur1;\n	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\n	while(tmp_accountid is not null) DO\n		IF tmp_days<=-30 THEN\n			SET @remind_type=\'自动任务之服务过期提醒\';\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'ServiceCharge\' and content like \'自动任务之服务过期提醒%\') THEN\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务