INSERT INTO `ld_emailtemplates` VALUES ('Public','合同签约邮件模板',NULL,'合同签约日期','<p>X 经理/总： 您好！</p><p>您的合同签约日期即将到期。为了保证您能继续使用我司提供的服务，请您尽快续费。<br/></p>',0,20,0),('Public','事务邮件',NULL,'X 经理/总： 您好！ 非常荣幸能够代表我公司与您联系。 我是 XXXX公司的 XXX（职位）的 XXX（姓名），今天将您所感兴趣的我司 产品报价及相关介绍发送给您，请您查阅！ 如果邮件中有任何不清楚的地方或者您需要我们提供任何帮助，请您联系 我，电话： ********* ，或联系 XXX（该客户的具体主管以上负责人）手机号： XXXX。','<p>v&gt; <span style=\"font-size: 28px; font-family: Helvetica;\">X </span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">经理</span><span style=\"font-size: 28px; font-family: Helvetica;\">/</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">总： <br/></span></p><p><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">您好！ 非常荣幸能够代表我公司与您联系。 我是 </span><span style=\"font-size: 28px; font-family: Helvetica;\">XXXX</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">公司的 </span><span style=\"font-size: 28px; font-family: Helvetica;\">XXX</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">（职位）的 </span><span style=\"font-size: 28px; font-family: Helvetica;\">XXX</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">（姓名），今天将您所感兴趣的我司 产品报价及相关介绍发送给您，请您查阅！ 如果邮件中有任何不清楚的地方或者您需要我们提供任何帮助，请您联系 我，电话： </span><span style=\"font-size: 28px; font-family: Helvetica;\">********* </span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">，或联系 </span><span style=\"font-size: 28px; font-family: Helvetica;\">XXX</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">（该客户的具体主管以上负责人）手机号： </span><span style=\"font-size: 28px; font-family: Helvetica;\">XXXX</span><span style=\"font-size: 28px; font-family: STSongStd-Light-Acro;\">。&nbsp;</span></p>',0,21,1),('Public','问候邮件',NULL,'X 经理/总： 您好！ 在这个阳关灿烂的日子里，祝您身体健康，心情愉快！ （在这个特别的日子里，为您送上最真挚的祝福，祝您：生日快乐！工作 顺利！） XXX公司 XX敬上','<p>v&gt; <span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">X </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">经理</span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">/</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">总： </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">您好！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">在这个阳关灿烂的日子里，祝您身体健康，心情愉快！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">（在这个特别的日子里，为您送上最真挚的祝福，祝您：生日快乐！工作 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">顺利！） </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">XXX</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">公司 </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">XX</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">敬上</span></p>',0,22,1),('Public','新年祝福',NULL,'X 经理/总： 新年好！ 值此 2012 新年来临之际， XXXX（公司）向贵公司表示最衷心的感谢和最诚 挚的祝福，感谢您长期以来对我们的支持和信任！ 在过去的一年中，我们的团队在您的支持、鼓励、批评下得到了一定的成 长。未来的中国是服务的王国，得服务真谛者得天下！你我携手共同为车主创 造出体验更加温馨、融洽、激情的消费天空。您的标准就是我们努力的方向。 在私下直言批评的是我们的真朋友！请提高您对我们的标准！ 让我们共同携手创造明天、后天 !我们的团队还很幼稚，需要指点、批评、 鼓励等各种成长的 “营养素 ”，这是您赐予我们最有价值的礼物。 愿我们成为您生命中的礼物，虽然不期而至闯入您的世界，但从此为您打 开全新的一扇窗 ——那一片天空下，生命真挚而温暖，彼此尊重、呵护，彼此 温暖。这是我们共同的愿景，这是我们共同的理想！ 新春来临，万象更新， XXXX全体员工衷心祝愿贵公司大展宏图、事业兴 旺！顺祝春节愉快，身体健康，阖家欢乐！ XXXX公司','<p>v&gt; <span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">X </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">经理</span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">/</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">总： </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">新年好！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">值此 </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">2012 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">新年来临之际， </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">XXXX</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">（公司）向贵公司表示最衷心的感谢和最诚 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">挚的祝福，感谢您长期以来对我们的支持和信任！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">在过去的一年中，我们的团队在您的支持、鼓励、批评下得到了一定的成 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">长。未来的中国是服务的王国，得服务真谛者得天下！你我携手共同为车主创 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">造出体验更加温馨、融洽、激情的消费天空。您的标准就是我们努力的方向。 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">在私下直言批评的是我们的真朋友！请提高您对我们的标准！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">让我们共同携手创造明天、后天 </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">!</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">我们的团队还很幼稚，需要指点、批评、 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">鼓励等各种成长的 “营养素 ”，这是您赐予我们最有价值的礼物。 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">愿我们成为您生命中的礼物，虽然不期而至闯入您的世界，但从此为您打 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">开全新的一扇窗 ——那一片天空下，生命真挚而温暖，彼此尊重、呵护，彼此 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">温暖。这是我们共同的愿景，这是我们共同的理想！ </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">新春来临，万象更新， </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">XXXX</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">全体员工衷心祝愿贵公司大展宏图、事业兴 </span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">旺！顺祝春节愉快，身体健康，阖家欢乐！ </span><span style=\";font-size:28px;font-family:Helvetica;color:rgb(0,0,0)\">XXXX</span><span style=\";font-size:28px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)\">公司</span></p>',0,23,1);
