INSERT INTO `ld_faq` VALUES (260512,'FAQ2','0','试用测试','完全没问题','常见问题','已审批',1,1,1,'2018-01-03 15:56:58','2020-11-16 15:13:45',NULL,1,NULL,0,0,NULL,'未提交',0,NULL,NULL,0,NULL,0),(272784,'FAQ7','254264','PC端“工作汇报”模块，如何修改“一天的工作开始于前一天晚上，创建工作汇报吧！”？','1.连接数据库，新建查询“select * from ld_desk where labelbol = \'COOPERATIVEWORKTITLE\';”（如图一）\n\n2.“fieldlabel”列直接修改即可','常见问题','草案',1,1,0,'2020-11-16 15:15:11','2020-11-16 15:15:11',NULL,0,'软件安装',0,0,NULL,'未提交',0,NULL,NULL,0,NULL,0),(272785,'FAQ8','259942','问题：CRM账套从老版本升级到左右结构版本时，报错该如何处理？','解决方法：直接替换补丁（注：先备份文件在替换）\n\n补丁替换路径：D:\\ldcrm\\www\\crm\\includ','常见问题','草案',1,1,0,'2020-11-16 15:15:46','2020-11-16 15:15:46',NULL,0,'软件安装',0,0,NULL,'未提交',0,NULL,NULL,0,NULL,0),(272786,'FAQ9','254681','如何查询单据的源单号？','1.（例如在“合同订单”模块列表查找“报价单”编号）\n系统设置-页面设置-选择“合同订单”页面设置，点击“新增字段”，弹出框“字段类型”选择“引用字段”，“引用对象”选择“报价单”，“引用字段”选择“报价单号”，勾选“保存到数据库”点击保存\n\n注：不保存到数据库，无法在“合同订单”模块列表表头显示该字段\n\n\n\n2.合同订单模块列表界面点击“管理分类”，编辑分类，可用字段找到新增的“报价单源单号”字段移动至“已选字段”，点击保存\n\n\n\n3.接下来就可以点击“基本查找”，查找“报价单源单”字段','常见问题','草案',1,1,0,'2020-11-16 15:16:18','2020-11-16 15:16:18',NULL,0,'',0,0,NULL,'未提交',0,NULL,NULL,0,NULL,0),(272787,'FAQ10','259943','Linux服务器CRM软件 PHP7升级方法说明','1.定位到下载目录\ncd /home/www/upload/   \n\n2.下载升级包\nwget https://61mis.com/V8.0.3.zip\n\n3.解压升级包\nunzip V8.0.3.zip\n\n4.覆盖CRM程序,路径需要根据CRM程序路径修改\nunalias cp\ncp -r crm/* /home/www/html/crm/\n\n5.覆盖升级后，打开CRM登录界面，等待系统自动执行完升级脚本，清除缓存刷新后即可正常使用','常见问题','草案',1,1,0,'2020-11-16 15:17:00','2020-11-16 15:17:00',NULL,0,'其他',0,0,NULL,'未提交',0,NULL,NULL,0,NULL,0);
