0.00'),(722454,'budgetcost','0.000','2000.000'),(722455,'actualcost','0.000','1200.000'),(722456,'expectedresponse','','极佳'),(722457,'expectedrevenue','0.000','2500.000'),(722458,'expectedsalescount','0.00','1500.00'),(722459,'actualsalescount','0.00','1800.00'),(722460,'expectedresponsecount','0.00','120.00'),(722461,'actualresponsecount','0.00','150.00'),(722462,'expectedroi','0.000','150.000'),(722463,'actualroi','0.000','180.000'),(722464,'deleted','0','1'),(722465,'deleted','0','1'),(722466,'deleted','0','1'),(722467,'deleted','0','1'),(722468,'deleted','0','1'),(722469,'deleted','0','1'),(722470,'deleted','0','1'),(722471,'deleted','0','1'),(722472,'deleted','0','1'),(722473,'deleted','0','1'),(722474,'deleted','0','1'),(722475,'deleted','0','1'),(722476,'deleted','0','1'),(722477,'deleted','0','1'),(722478,'deleted','0','1'),(722479,'deleted','0','1'),(722480,'notecontent','&lt;p&gt;&lt;span style=&quot;;font-size:43px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第二章 &lt;/span&gt;&lt;span style=&quot;;font-size:43px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;员工日常行为规范&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第一条 员工必须遵纪守法，自觉维护社会公共秩序，如有违反国家法规者，一 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;律解职。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第二条 员工必须严格遵守公司各项规章制度，服从指挥。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第三条 员工对内应善尽本份，认真工作，爱惜公物，减少浪费，提升品质；对 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;外应严守职务机密，维护公司形象。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第四条 员工应树立主人翁精神、增强责任感。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第五条 员工应树立良好的工作态度，着工作服，穿着整洁，积极上进，培养公 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;司荣誉感。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第六条 公司员工应和众共济，通力合作，友爱相处。不得滋生事端，扰乱秩序， &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;不得有组织派系，搬弄是非及争吵逗殴以防碍公司士气与团结。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第七条 员工应时刻维护公司利益，勇于制止任何损害公司利益的事情。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第八条 认真接听、转接公司电话，做好电话留言； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第九条 热情接待公司来访人员； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十条 对公司输出的邮件、传真、信息等必须及时与客户确认查询。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十一条 员工按照有关规定申领办公用品，所有从公司申领的用品均为公司财 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;物，要妥善保管、正确使用，不能占为己有，离职时须交还。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十二条 员工上班时间内不得兼差或从事其它危害公司业务的行为 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十三条 员工承办事务不得收受馈赠或回扣，亦不得借机为自己或他人图利。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十四条 员工应奉公守法，不得假籍职权贪污舞弊，亦不得假籍公司名义在外 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;招摇撞骗。不得侵吞公款。凡发现有经济不规行为，一般不宜担任领 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;导职务，数额巨大的应送公安部门，追究刑事责任。 &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;第十五条 公司员工在职务上，应注意下列事情；&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:Helvetica;color:rgb(0,0,0)&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;．确实掌握及了解本身职务与工作内容范围； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:Helvetica;color:rgb(0,0,0)&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;．处理事物应明确、负责、重时效，凡事应今天事今天毕； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:Helvetica;color:rgb(0,0,0)&quot;&gt;3&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;．交办事情完成后，应主动报告经理或交办部门知晓； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:Helvetica;color:rgb(0,0,0)&quot;&gt;4&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;．服从组织体制及规定，团结谐和，排除本位主义，以公司为重； &lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:Helvetica;color:rgb(0,0,0)&quot;&gt;5&lt;/span&gt;&lt;span style=&quot;;font-size:24px;font-family:STSongStd-Light-Acro;color:rgb(0,0,0)&quot;&gt;．工作如有疑难，应即请示上级，不得借故拖延，积压或擅做主张。 &lt;/span&gt;&lt;/p&gt;','&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: 楷体, 楷体_GB2312, SimKai; font-size: 14px;&quot;&gt;第二章 员工日常行为规范&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 10px; font-family: 楷体, 楷体_GB2312, SimKai;&quot;&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;第一条 员工必须遵纪守法，自觉维护社会公共秩序，如有违反国家法规者，一 律解职。 第二条 员工必须严格遵守公司各项规章制度，服从指挥。 第三条 员工对内应善尽本份，认真工作，爱惜公物，减少浪费，提升品质；对 外应严守职务机密，维护公司形象。 第四条 员工应树立主人翁精神、增强责任感。 第五条 员工应树立良好的工作态度，着工作服，穿着整洁，积极上进，培养公 司荣誉感。 第六条 公司员工应和众共济，通力合作，友爱相处。不得滋生事端，扰乱秩序， 不得有组织派系，搬弄是非及争吵逗殴以防碍公司士气与团结。 第七条 员工应时刻维护公司利益，勇于制止任何损害公司利益的事情。 第八条 认真接听、转接公司电话，做好电话留言； 第九条 热情接待公司来访人员； 第十条 对公司输出的邮件、传真、信息等必须及时与客户确认查询。 第十一条 员工按照有关规定申领办公用品，所有从公司申领的用品均为公司财 物，要妥善保管、正确使用，不能占为己有，离职时须交还。 第十二条 员工上班时间内不得兼差或从事其它危害公司业务的行为 第十三条 员工承办事务不得收受馈赠或回扣，亦不得借机为自己或他人图利。 第十四条 员工应奉公守法，不得假籍职权贪污舞弊，亦不得假籍公司名义在外 招摇撞骗。不得侵吞公款。凡发现有经济不规行为，一般不宜担任领 导职务，数额巨大的应送公安部门，追究刑事责任。 第十五条 公司员工在职务上，应注意下列事情；&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;．确实掌握及了解本身职务与工作内容范围； &lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;．处理事物应明确、负责、重时效，凡事应今天事今天毕； &lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;3&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;．交办事情完成后，应主动报告经理或交办部门知晓； &lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;4&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;．服从组织体制及规定，团结谐和，排除本位主义，以公司为重； &lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;5&lt;/span&gt;&lt;span style=&quot;font-size: 10px; color: rgb(0, 0, 0);&quot;&gt;．工作如有疑难，应即请示上级，不得借故拖延，积压或擅做主张。&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 24px; font-family: STSongStd-Light-Acro; color: rgb(0, 0, 0);&quot;&gt; &lt;/span&gt;&lt;/p&gt;'),(722481,'notecontent','&lt;div class=&quot;pro_box&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; height: 170px; width: 1200px; color: rgb(102, 102, 102); font-family: &amp;quot;Microsoft YaHei&amp;quot;, 微软雅黑, tahoma, arial, simsun, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);&quot;&gt;&lt;div class=&quot;pro_right&quot; style=&quot;padding: 20px 0px 0px; margin: 0px; max-height: 999999px; float: left; width: 980px;&quot;&gt;&lt;p class=&quot;title&quot; style=&quot;padding: 0px; margin-top: 0px; margin-bottom: 15px; max-height: 999999px; color: rgb(21, 119, 187); height: 34px; line-height: 34px;&quot;&gt;&lt;strong style=&quot;padding: 0px; margin: 0px; max-height: 999999px; font-size: 18px;&quot;&gt;记录客户资料，减少客户资料丢失&lt;/strong&gt;&amp;nbsp;&mdash;&mdash; 取代Excel或笔记本，减少员工离职致客户流失&lt;/p&gt;&lt;p class=&quot;depict&quot; style=&quot;padding: 0px; margin-top: 10px; margin-bottom: 0px; max-height: 999999px; color: rgb(153, 153, 153); line-height: 22px; font-size: 14px;&quot;&gt;完善的客户资料管理功能，可对客户进行分门别类的管理，方便查询，每个客户的状态、历史跟进情况都一目了然。即使员工离职他的客户资料、跟进情况也都完整的保留下来不会流失，新人很容易接手。当工作基于销售360进行，操作都有历史记录可查，5年后，10年后，今天的工作记录依然可以查询到。&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pro_box&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; height: 170px; width: 1200px; color: rgb(102, 102, 102); font-family: &amp;quot;Microsoft YaHei&amp;quot;, 微软雅黑, tahoma, arial, simsun, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);&quot;&gt;&lt;div class=&quot;pro_img proimg02&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; background: url(&amp;quot;http://71mis.cn/web_xs360/webimages/pro_value.png&amp;quot;) 15px -160px no-repeat; float: left; height: 167px; width: 200px;&quot;&gt;&lt;/div&gt;&lt;div class=&quot;pro_right&quot; style=&quot;padding: 20px 0px 0px; margin: 0px; max-height: 999999px; float: left; width: 980px;&quot;&gt;&lt;p class=&quot;title&quot; style=&quot;padding: 0px; margin-top: 0px; margin-bottom: 15px; max-height: 999999px; color: rgb(21, 119, 187); height: 34px; line-height: 34px;&quot;&gt;&lt;strong style=&quot;padding: 0px; margin: 0px; max-height: 999999px; font-size: 18px;&quot;&gt;团队协作&lt;/strong&gt;&amp;nbsp;&mdash;&mdash; 成员间共享协作，数据实时同步，增加工作效率&lt;/p&gt;&lt;p class=&quot;depict&quot; style=&quot;padding: 0px; margin-top: 10px; margin-bottom: 0px; max-height: 999999px; color: rgb(153, 153, 153); line-height: 22px; font-size: 14px;&quot;&gt;团队中每个人都有单独的账户，业务员录入的客户资料及拜访跟进情况，上级领导就可以查看到，并可对其进行批注。上级可以给下级分配工作任务并监控完成情况，管理人员通过电脑或手机就能实时了解下属的工作情况。告别过去下属定期向上级提交自己的客户资料的方式，达到数据的实时同步。&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pro_box&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; height: 170px; width: 1200px; color: rgb(102, 102, 102); font-family: &amp;quot;Microsoft YaHei&amp;quot;, 微软雅黑, tahoma, arial, simsun, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);&quot;&gt;&lt;div class=&quot;pro_img proimg03&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; background: url(&amp;quot;http://71mis.cn/web_xs360/webimages/pro_value.png&amp;quot;) 15px -330px no-repeat; float: left; height: 167px; width: 200px;&quot;&gt;&lt;/div&gt;&lt;div class=&quot;pro_right&quot; style=&quot;padding: 20px 0px 0px; margin: 0px; max-height: 999999px; float: left; width: 980px;&quot;&gt;&lt;p class=&quot;title&quot; style=&quot;padding: 0px; margin-top: 0px; margin-bottom: 15px; max-height: 999999px; color: rgb(21, 119, 187); height: 34px; line-height: 34px;&quot;&gt;&lt;strong style=&quot;padding: 0px; margin: 0px; max-height: 999999px; font-size: 18px;&quot;&gt;待办事项/工作任务提醒&lt;/strong&gt;&amp;nbsp;&mdash;&mdash; 您忠实的个人助理&lt;/p&gt;&lt;p class=&quot;depict&quot; style=&quot;padding: 0px; margin-top: 10px; margin-bottom: 0px; max-height: 999999px; color: rgb(153, 153, 153); line-height: 22px; font-size: 14px;&quot;&gt;待办任务提醒、客户生日提醒、客户生日自动发祝福，节假日祝福自动处理，让您的工作省时省力。通过完善的任务功能，能让您的工作目标清晰，井然有序。&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pro_box&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; height: 170px; width: 1200px; color: rgb(102, 102, 102); font-family: &amp;quot;Microsoft YaHei&amp;quot;, 微软雅黑, tahoma, arial, simsun, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);&quot;&gt;&lt;div class=&quot;pro_img proimg04&quot; style=&quot;padding: 0px; margin: 0px; max-height: 999999px; background: url(&amp;quot;http://71mis.cn/web_xs360/webimages/pro_value.png&amp;quot;) 15px -660px no-repeat; float: left; height: 167px; width: 200px;&quot;