INSERT INTO `ld_monthreport` VALUES (2,'本月计划(上月填写)：熟悉公司CRM产品，前台功能操作以及后台调试操作，理解CRM对于客户的帮助和价值。<br />\r\n<br />\r\n本月总结:','<p>\r\n	第一：通过筛选，电话拜访上海本地客户，挖掘到潜在客户。\r\n</p>\r\n<p>\r\n	第二：深入熟悉公司产品，要能达到一旦上门，做到游刃有余，能解决客户当前需求。\r\n</p>\r\n<p>\r\n	<br />\r\n</p>','2014-08-01','2014-08-31','2014-08-27 16:21:51',26,2014,8,'2014-08-27 16:21:51',0,1);
