INSERT INTO `ld_notes` VALUES (259658,'DOC2','公司规章-公司规章制度',NULL,'','默认',NULL,'I',NULL,1,0,NULL,'未提交',NULL,81,51,1,'2017-10-11 12:05:13','2020-11-16 14:52:02',NULL,1,NULL,0,NULL,NULL,0,NULL,0),(259659,'DOC3','公司规章-公司规章制度',NULL,'<p>ceshi</p>','规章制度',NULL,'I',NULL,1,0,NULL,'未提交',NULL,51,51,1,'2017-10-11 12:07:53','2020-11-16 14:54:47',NULL,1,NULL,0,NULL,NULL,0,NULL,0),(261093,'DOC7','11',NULL,'','默认',NULL,NULL,NULL,0,0,NULL,'未提交',NULL,51,51,1,'2018-04-13 20:42:36','2020-11-16 14:54:47',NULL,1,NULL,0,NULL,NULL,0,NULL,0),(262901,'DOC12','知识',NULL,'<p>试用测试</p>','1',NULL,'I',NULL,0,0,NULL,'未提交',NULL,51,51,1,'2018-10-06 19:59:31','2020-11-16 14:54:47',NULL,1,NULL,0,NULL,NULL,0,NULL,0),(263636,'DOC13','知识',NULL,'<p><a href=\"http://www.baidu.com\" target=\"_self\" title=\"打开百度\">百度</a><br/></p>','1',NULL,'I',NULL,1,0,NULL,'未提交',NULL,51,51,1,'2018-11-23 15:59:26','2020-11-16 14:54:47',NULL,1,NULL,0,NULL,NULL,0,NULL,0),(272781,'DOC14','员工日常行为规范',NULL,'<p style=\"text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-family: 楷体, 楷体_GB2312, SimKai; font-size: 14px;\">第二章 员工日常行为规范&nbsp;</span></p><p><span style=\"font-size: 10px; font-family: 楷体, 楷体_GB2312, SimKai;\"><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">第一条 员工必须遵纪守法，自觉维护社会公共秩序，如有违反国家法规者，一 律解职。 第二条 员工必须严格遵守公司各项规章制度，服从指挥。 第三条 员工对内应善尽本份，认真工作，爱惜公物，减少浪费，提升品质；对 外应严守职务机密，维护公司形象。 第四条 员工应树立主人翁精神、增强责任感。 第五条 员工应树立良好的工作态度，着工作服，穿着整洁，积极上进，培养公 司荣誉感。 第六条 公司员工应和众共济，通力合作，友爱相处。不得滋生事端，扰乱秩序， 不得有组织派系，搬弄是非及争吵逗殴以防碍公司士气与团结。 第七条 员工应时刻维护公司利益，勇于制止任何损害公司利益的事情。 第八条 认真接听、转接公司电话，做好电话留言； 第九条 热情接待公司来访人员； 第十条 对公司输出的邮件、传真、信息等必须及时与客户确认查询。 第十一条 员工按照有关规定申领办公用品，所有从公司申领的用品均为公司财 物，要妥善保管、正确使用，不能占为己有，离职时须交还。 第十二条 员工上班时间内不得兼差或从事其它危害公司业务的行为 第十三条 员工承办事务不得收受馈赠或回扣，亦不得借机为自己或他人图利。 第十四条 员工应奉公守法，不得假籍职权贪污舞弊，亦不得假籍公司名义在外 招摇撞骗。不得侵吞公款。凡发现有经济不规行为，一般不宜担任领 导职务，数额巨大的应送公安部门，追究刑事责任。 第十五条 公司员工在职务上，应注意下列事情；</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">1</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">．确实掌握及了解本身职务与工作内容范围； </span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">2</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">．处理事物应明确、负责、重时效，凡事应今天事今天毕； </span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">3</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">．交办事情完成后，应主动报告经理或交办部门知晓； </span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">4</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">．服从组织体制及规定，团结谐和，排除本位主义，以公司为重； </span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">5</span><span style=\"font-size: 10px; color: rgb(0, 0, 0);\">．工作如有疑难，应即请示上级，不得借故拖延，积压或擅做主张。</span></span><span style=\"font-size: 24px; font-family: STSongStd-Light-Acro; color: rgb(0, 0, 0);\"> </span></p>','企业规章制度',NULL,'I',NULL,1,0,NULL,'未提交',NULL,1,1,1,'2020-11-16 15:04:38','2020-11-18 13:36:18',NULL,0,NULL,0,NULL,NULL,0,NULL,0),(272782,'DOC15','企业文化',NULL,'<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(1)企业精神：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(2)工作作风：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(3)集团模式：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(4)管理理念：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(5)市场观：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(6)内部管理模式：OEC管理、市场链。</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(7)质量方针：</span><br style=\"content: &quot;&quot;; display: block; width: 705px; height: 0px; margin: 20px 0px; color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(51, 51, 51); font-family: &quot;PingFang SC&quot;, &quot;Lantinghei SC&quot;, &quot;Microsoft YaHei&quot;, arial, 宋体, sans-serif, tahoma; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\">(8)服务新标准：</span></p>','企业文化平台',NULL,'I',NULL,1,0,NULL,'未提交',NULL,1,1,0,'2020-11-16 15:10:10','2020-11-16 15:10:10',NULL,0,NULL,0,NULL,NULL,0,NULL,0),(272783,'DOC16','产品介绍',NULL,'<p><span style=\"color: rgb(153, 153, 153); font-family: &quot;Microsoft YaHei&quot;, 微软雅黑, tahoma, arial, simsun, 宋体; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\">完善的客户资料管理功能，可对客户进行分门别类的管理，方便查询，每个客户的状态、历史跟进情况都一目了然。即使员工离职他的客户资料、跟进情况也都完整的保留下来不会流失，新人很容易接手。当工作基于销售360进行，操作都有历史记录可查，5年后，10年后，今天的工作记录依然可以查询到。</span></p>','产品介绍',NULL,'I',NULL,1,0,NULL,'未提交',NULL,1,1,1,'2020-11-16 15:11:38','2020-11-16 15:12:49',NULL,0,NULL,0,NULL,NULL,0,NULL,0);
