/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_projecttask_distributetime` BEFORE UPDATE ON `ld_projecttask` FOR EACH ROW 
BEGIN

IF @disable_triggers IS NULL THEN
 
		
