INSERT INTO `ld_publicannouncement` VALUES (259660,'部门通知','重要通知','2017-10-11','2017-10-11','<p>部门职责调整通知：<br/></p><p>&nbsp; 2017年XX月，由于XX原因，职责调整如下：</p><p>&nbsp; &nbsp;</p>',51,51,1,'2017-10-11 13:27:12','2020-12-25 13:34:54',NULL,0,0,NULL,0,NULL,0,'未提交',0,NULL,NULL),(272969,'十一国庆节期间燃气安全工作通知','重要通知','2020-11-19','2020-11-19','<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 12px;\">&nbsp;<span style=\"font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0);\">十一国庆节期间燃气安全工作通知</span></span></p><p><span style=\"font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 12px;\">各镇人民政府、街道办事处、 城郊管委会及各燃气经营企业： 为全面贯彻落实国家和省、市有关安全工作的指示精神，确保燃 气安全运行，现就做好“十一”国庆节期间的燃气安全工作的有关事 项通知如 ... 关于加强国庆期间安全燃气工作的通知各燃气经营企业、 各用气单位： 中秋、国庆即将到来，为确保此期间的燃气安全生产无事故发 生，营造欢乐、喜庆的节日氛围，根据我局安全生产工作的部署，结 合我区燃气行业现状，就中秋、国庆安全生 ... 纪念中国人民抗日战争 胜利 70 周年征文启事 201X年 9 月 3 日是中国人民抗日战争暨世界反 法西斯战争胜利 70 周年纪念日，也是中国首个法定的“中国人民抗日 战争胜利纪念日”。这一天，天安门广场盛大的阅兵仪式吸引了全球 的目光；习总书 ... 做好纪念 </span></p>',1,1,1,'2020-11-19 11:38:43','2020-12-25 13:33:41',NULL,0,0,NULL,0,NULL,0,'未提交',0,NULL,NULL);
