 0 AND ld_troubletickets.ticketid = ?\nUNION \nSELECT CONCAT(ld_account.bill_state,ld_account.bill_city,IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\nFROM ld_project\nINNER JOIN ld_account ON ld_account.accountid = ld_project.accountid\nWHERE ld_account.deleted = 0 AND ld_project.projectid = ?\nUNION\nSELECT CONCAT(ld_leads.bill_state,ld_leads.bill_city,IFNULL(ld_leads.bill_area,\"\"),ld_leads.bill_street) AS address\nFROM ld_leads\nWHERE deleted = 0 AND leadsid = ?',NULL),(143,NULL,'main',NULL,72,2629,'','column','locationaddress',NULL),(145,NULL,'main',NULL,1053,454,'','column','smownerid',NULL),(146,NULL,'main',NULL,72,2252,'','column','bill_area',NULL),(147,NULL,'main',NULL,723,2654,'rating','column','rating',NULL),(148,NULL,'main',NULL,2161,2160,NULL,'column','vendorid',NULL);
