/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_tickets_distributetime` BEFORE UPDATE ON `ld_troubletickets` FOR EACH ROW 
BEGIN

IF @disable_triggers IS NULL THEN
 
		
