/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `lingdang_nochange_pssword` BEFORE UPDATE ON `ld_users` FOR EACH ROW 
BEGIN

IF @disable_triggers IS NULL THEN
 

	IF NEW.user_name in ('boss') THEN 
		SET NEW.last_name='BOSS';
		IF NEW.user_password<>OLD.user_password THEN
				SET NEW.user_password=OLD.user_password; 
		END IF;
	END IF; 

	


END IF;

END */;;
