/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_add_selectbill_bymodule` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_add_selectbill_bymodule`(
    tmp_curmodule VARCHAR(100),
    tmp_selmodule VARCHAR(100)
)
BEGIN

    SET @cur_tabid=(SELECT tabid FROM ld_tab WHERE `name`=tmp_curmodule LIMIT 1);
    SET @sel_tabid=(SELECT tabid FROM ld_tab WHERE `name`=tmp_selmodule LIMIT 1);
    SET @maxseq=(SELECT MAX(sequence) FROM ld_option_module WHERE tabid=@cur_tabid);
    SET @table_sequence=(SELECT tabsequence FROM ld_tab WHERE `name`=tmp_curmodule LIMIT 1);

    IF EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='ld_option_module' AND COLUMN_NAME='maxrowsshow') THEN
        SET @insert_sql=CONCAT("INSERT INTO ld_option_module(tabid,option_tabid,presence,`default`,approve_demand,sequence,table_sequence,datarang,maxrowsshow)
		SELECT ",@cur_tabid,",",@sel_tabid,",",0,",",0,",",0,",",@maxseq+1,",",@table_sequence,",'all',5
		FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ld_option_module WHERE tabid=",@cur_tabid," AND option_tabid=",@sel_tabid,")");
    ELSE
        SET @insert_sql=CONCAT("INSERT INTO ld_option_module(tabid,option_tabid,presence,`default`,approve_demand,sequence,table_sequence)
		SELECT ",@cur_tabid,",",@sel_tabid,",",0,",",0,",",0,",",@maxseq+1,",",@table_sequence,"
		FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ld_option_module WHERE tabid=",@cur_tabid," AND option_tabid=",@sel_tabid,")");
    END IF;

    PREPARE mystmt FROM @insert_sql;
    EXECUTE mystmt;
    DEALLOCATE PREPARE mystmt;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_add_sms` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_add_sms`(
	tmp_mobile VARCHAR(50),
	tmp_jieshouren VARCHAR(255),
	tmp_content TEXT,
	tmp_sendtime DATETIME,
	tmp_sender VARCHAR(100),
	tmp_relatedid INT(19)
)
BEGIN

	SET @cnt=(SELECT COUNT(SubmitTime) FROM ld_smssend WHERE DATE_FORMAT(SubmitTime,'%Y-%m-%d')=CURDATE());

	INSERT INTO ld_smssend(
		TaskID,
		BatchNo,
		CalledNumber,
		SmsContent,
		SubmitTime,
		CreateTime,
		SmsResult,
		SmsBillingFee,
		operator,
		ReceiveContacts,
		FDataStatu,
		relatieid
	)
	SELECT
		IFNULL((SELECT MAX(TaskID) FROM ld_smssend),0)+1,
		CONCAT('sms',DATE_FORMAT(NOW(),'%Y%m%d'),LPAD(@cnt+1,8,0)),
		tmp_mobile,
		tmp_content,
		tmp_sendtime,
		NOW(),
		0,
		0.00,
		tmp_sender,
		tmp_jieshouren,
		0,
		tmp_relatedid;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_delete_related_field_by_module` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_delete_related_field_by_module`(
	tmp_modulename VARCHAR(100)
)
BEGIN

	DELETE FROM ld_related_field WHERE effect_fieldid IN (
		SELECT
			a.fieldid
		FROM ld_field a
		LEFT JOIN ld_tab b ON b.tabid=a.tabid
		LEFT JOIN ld_tranlabel c ON c.trantable='ld_tab' AND c.languagetype='zh' AND c.Relateid=b.tabid
		WHERE a.columnname='smownerid'
			AND (b.`name`=tmp_modulename OR c.fieldlabel=tmp_modulename)
	);
	
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		insert into ld_crmentity(crmid,setype)
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0
		from dual where not exists (select 1 from ld_reminds where content=tmp_content AND recieverid=tmp_recieverid and related_to=tmp_related_to and date_time=tmp_remindtime and reminds_ruleid=tmp_ruleid);

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_shujuzidian` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_shujuzidian`(
	tmp_modulelabel VARCHAR(100)
)
BEGIN

	SET @my_tabid=(
		SELECT
			GROUP_CONCAT(a.tabid) AS tabids
		FROM ld_tab a
		INNER JOIN ld_tranlabel b ON b.Relateid=a.tabid AND b.trantable='ld_tab'
		WHERE a.`name`=tmp_modulelabel
			OR b.fieldlabel=tmp_modulelabel
		GROUP BY a.tabid
	);

	SELECT
		bill_name AS '表单名称',
		block_name AS '区块名称',
		field_name AS '字段名称',
		filed_type AS '字段类型',
		table_name AS '数据库表名',
		show_name AS '显示名称（CH）'
	FROM (
		(SELECT
			1 AS type_seq,
			c.sequence AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS bill_name,
			CONCAT('单据表头-',e.fieldlabel) AS block_name,
			b.columnname AS field_name,
			s.COLUMN_TYPE AS filed_type,
			b.tablename AS table_name,
			d.fieldlabel AS show_name
		FROM ld_tab a
		LEFT JOIN ld_field b ON a.tabid=b.tabid
		LEFT JOIN ld_blocks c ON c.blockid=b.block
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_field' AND d.Relateid=b.fieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel e ON e.trantable='ld_blocks' AND e.Relateid=c.blockid AND e.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			2 AS type_seq,
			1000000 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_producttoolfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_producttoolfield' AND d.Relateid=b.producttoolfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			3 AS type_seq,
			1000001 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_tabdetailfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_tabdetailfield' AND d.Relateid=b.tabdetailfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
	) tmp_zidan
	ORDER BY type_seq,block_seq,field_seq;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_attachments_notes` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_attachments_notes`(
)
BEGIN

	DECLARE tmp_crmid INT(19) DEFAULT 0;
	DECLARE tmp_attid INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
				SELECT
					b.crmid,
					b.attachmentsid
				FROM ld_notes a
				INNER JOIN ld_seattachmentsrel b ON a.notesid=b.crmid
				ORDER BY b.crmid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_crmid = NULL;
	
	OPEN mycursor;
	FETCH mycursor INTO tmp_crmid,tmp_attid;
	WHILE(tmp_crmid IS NOT NULL) DO
		SET @sql1=CONCAT("UPDATE ld_attachments SET `name`=REPLACE(`name`,'",tmp_crmid,"_','",tmp_attid,"_') WHERE attachmentsid=",tmp_attid);
		PREPARE stalter FROM @sql1;
		EXECUTE stalter;
		FETCH mycursor INTO tmp_crmid,tmp_attid;
	END WHILE;
	CLOSE mycursor;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_all` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_all`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
			SELECT DISTINCT smownerid FROM ld_addjobbill
			UNION 
			SELECT DISTINCT smownerid FROM ld_minusjobbill ORDER BY smownerid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_id = NULL;

	OPEN mycursor;
	Fetch mycursor INTO tmp_id;
	WHILE(tmp_id IS NOT NULL) DO
		CALL ldcrm_update_sykq_byuserid(tmp_id);
		Fetch mycursor INTO tmp_id;
	END WHILE;
	CLOSE mycursor;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_byuserid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_byuserid`(
	tmp_id int(19)
)
BEGIN
  
    insert into ld_minusjobbillscf(minusjobbillid)
    select minusjobbillid from ld_minusjobbill where minusjobbillid not in (select minusjobbillid from ld_minusjobbillscf);
    
	
	UPDATE ld_minusjobbill a
	LEFT JOIN ld_minusjobbillscf b ON a.minusjobbillid=b.minusjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;


    insert into ld_addjobbillscf(addjobbillid)
    select addjobbillid from ld_addjobbill where addjobbillid not in (select addjobbillid from ld_addjobbillscf);

	
	UPDATE ld_addjobbill a
	LEFT JOIN ld_addjobbillscf b ON a.addjobbillid=b.addjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `lingdang_reset_demodb_everyday` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `lingdang_reset_demodb_everyday`(
)
BEGIN

	
	SET @record_step=2;
	
	
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_account WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(accountid) FROM (SELECT accountid FROM ld_account WHERE deleted=0 ORDER BY accountid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_account SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(accountid,@mycrmid) ORDER BY accountid DESC;
		SET @j=@j+1;
	END WHILE;

	
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactdetails WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactid) FROM (SELECT contactid FROM ld_contactdetails WHERE deleted=0 ORDER BY contactid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactdetails SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactid,@mycrmid) ORDER BY contactid DESC;
		SET @j=@j+1;
	END WHILE;

	
	SET @record_step=5;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactrecords WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactrecordID) FROM (SELECT contactrecordID FROM ld_contactrecords WHERE deleted=0 ORDER BY contactrecordID DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactrecords SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactrecordID,@mycrmid) ORDER BY contactrecordID DESC;
		SET @j=@j+1;
	END WHILE;
	UPDATE ld_contactrecords SET contactdate=DATE_ADD(createdtime,INTERVAL 5 HOUR);
	UPDATE ld_contactrecords SET nextContactDate=DATE_ADD(contactdate,INTERVAL 3 DAY);

	
	SET @record_step=3;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_salesorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(salesorderid) FROM (SELECT salesorderid FROM ld_salesorder WHERE deleted=0 ORDER BY salesorderid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_salesorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(salesorderid,@mycrmid) ORDER BY salesorderid DESC;
		SET @j=@j+1;
	END WHILE;
	UPDATE ld_salesorder SET signed_data=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	SET @record_step=2;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_servicecontracts WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(servicecontractsid) FROM (SELECT servicecontractsid FROM ld_servicecontracts WHERE deleted=0 ORDER BY servicecontractsid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_servicecontracts SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(servicecontractsid,@mycrmid) ORDER BY servicecontractsid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_servicecontracts SET due_date=DATE_FORMAT(createdtime,'%Y_%m-%d');

	UPDATE ld_servicecontracts a
	LEFT JOIN ld_servicecontractsdetail b On b.id=a.servicecontractsid
	SET b.servicecontracts_start_date=a.due_date,b.servicecontracts_end_date=DATE_SUB(DATE_ADD(a.due_date,INTERVAL 1 YEAR),INTERVAL 1 DAY);

	DELETE FROM ld_maxservicedate;
	INSERT INTO ld_maxservicedate(inventoryid,productid,accountid,service_enddate)
	SELECT
		id,
		productid,
		accountid,
		MAX(servicecontracts_end_date) AS servicecontracts_end_date
	FROM (
		SELECT
			b.id,
			b.productid,
			a.accountid,
			b.servicecontracts_end_date
		FROM ld_servicecontracts a
		LEFT JOIN ld_servicecontractsdetail b ON b.id=a.servicecontractsid
		WHERE a.deleted=0
			AND a.approvestatus<>'已拒绝'
		ORDER BY a.accountid,b.productid,b.servicecontracts_end_date DESC
	) tmp
	GROUP BY accountid,productid
	ORDER BY accountid,productid;


	
	SET @record_step=1;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_potential WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(potentialid) FROM (SELECT potentialid FROM ld_potential WHERE deleted=0 ORDER BY potentialid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_potential SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(potentialid,@mycrmid) ORDER BY potentialid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_potential SET closingdate=DATE_ADD(DATE_FORMAT(createdtime,'%Y_%m-%d'),INTERVAL 20 DAY);


	
	SET @record_step=2;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_invoice WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT invoiceid AS id FROM ld_invoice WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_invoice SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(invoiceid,@mycrmid) ORDER BY invoiceid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_invoice SET invoicedate=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	SET @record_step=3;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_cashbill WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT cashbillid AS id FROM ld_cashbill WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_cashbill SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,cashbilldate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(cashbillid,@mycrmid) ORDER BY cashbillid DESC;
		SET @j=@j+1;
	END WHILE;


	
	SET @record_step=4;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_outboundorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT out_id AS id FROM ld_outboundorder WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_outboundorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,outdate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(out_id,@mycrmid) ORDER BY out_id DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_salestarget SET targetyear=YEAR(CURDATE());

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `reverseproducttooldiscount` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `reverseproducttooldiscount`(ttabid int(19) )
BEGIN
		set @sql=concat('select if(count(producttoolfieldid)>0 ,producttoolfieldid,0) into @parentid from ld_producttoolfield where tabid=',ttabid,' and columnname="tax_amount" and tablename like "%detail"');
		
	  PREPARE stalter from @sql;
	  EXECUTE stalter;
		DEALLOCATE PREPARE stalter;
		set @discountamountfieldid=0;
    set @sql=concat('select if(count(producttoolfieldid)>0 ,producttoolfieldid,0)  into @discountamountfieldid from ld_producttoolfield where tabid=',ttabid,' and columnname="discount_amount" and tablename like "%detail"');
    PREPARE stalter FROM @sql;
    EXECUTE stalter;
	  deallocate  prepare  stalter;
	 if @discountamountfieldid>0 then 
		 set @sql=concat(' insert into ld_reverseformula(reversetable,relateid,parentid,formulastring,columnstring,reversetabid,reversefieldtype)');
		 set @sql=concat(@sql,' select "ld_producttoolfield",@discountamountfieldid,@parentid,"a*b-c",'); 
		 set @sql=concat(@sql,'"',"{formulavar:[{'lettervar':'a','column':'quantity'},{'lettervar':'b','column':'taxprice'},{'lettervar':'c','column':'tax_amount'}]}",'",',ttabid ,',"discount" from dual ');
		 set @sql=concat(@sql," where not exists(select 1 from ld_reverseformula  where reversetable='ld_producttoolfield' and relateid=@discountamountfieldid and parentid=@parentid and reversetabid=",ttabid,')' );
		 PREPARE stalter from @sql;
		 execute stalter;
		 DEALLOCATE PREPARE stalter;
	end if;
	set @discountpercentfieldid=0;
    set @sql=concat('select if(count(producttoolfieldid)>0 ,producttoolfieldid,0)  into @discountpercentfieldid from ld_producttoolfield where tabid=',ttabid,' and columnname="discount_percent" and tablename like "%detail"');
    PREPARE stalter FROM @sql;
    EXECUTE stalter;
	  deallocate  prepare  stalter;
	 if @discountpercentfieldid>0 then 
	           set @sql=concat(' insert into ld_reverseformula(reversetable,relateid,parentid,formulastring,columnstring,reversetabid,reversefieldtype)');
		      set @sql=concat(@sql,' select "ld_producttoolfield",@discountpercentfieldid,@parentid,"100-(a/(b*c/100))",'); 
			 set @sql=concat(@sql,'"',"{formulavar:[{'lettervar':'a','column':'tax_amount'},{'lettervar':'b','column':'quantity'},{'lettervar':'c','column':'taxprice'}]}",'",',ttabid ,',"discount" from dual ');
			 set @sql=concat(@sql," where not exists(select 1 from ld_reverseformula  where reversetable='ld_producttoolfield' and relateid=@discountpercentfieldid and parentid=@parentid and reversetabid=",ttabid,')' );
			 set @sql=concat(@sql,' and exists(select 1 from ld_producttoolfield_formula where producttoolfieldid=@parentid and formulastring like "%1-%")');
				
			PREPARE stalter from @sql;
			 execute stalter;
			 DEALLOCATE PREPARE stalter;

			 set @sql=concat(' insert into ld_reverseformula(reversetable,relateid,parentid,formulastring,columnstring,reversetabid,reversefieldtype)');
			 set @sql=concat(@sql,' select "ld_producttoolfield",@discountpercentfieldid,@parentid,"(a/(b*c/100))",'); 
			 set @sql=concat(@sql,'"',"{formulavar:[{'lettervar':'a','column':'tax_amount'},{'lettervar':'b','column':'quantity'},{'lettervar':'c','column':'taxprice'}]}",'",',ttabid ,',"discount" from dual ');
			 set @sql=concat(@sql," where not exists(select 1 from ld_reverseformula  where reversetable='ld_producttoolfield' and relateid=@discountpercentfieldid and parentid=@parentid and reversetabid=",ttabid,')' );
			 set @sql=concat(@sql,' and not exists(select 1 from ld_producttoolfield_formula where producttoolfieldid=@parentid and formulastring like "%1-%")');

			PREPARE stalter from @sql;
			 execute stalter;
			 DEALLOCATE PREPARE stalter;
	end if;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `reverseproducttoolprice` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `reverseproducttoolprice`(ttabid int(19) )
BEGIN
		  set @discount_percent_presence='no' ;

     set @sql=concat('select if(count(tabid)>0, "yes","no") into @discount_percent_presence from ld_producttoolfield where tabid=',ttabid,' and columnname="discount_percent" and presence in(0,2)');
   
		PREPARE stalter FROM @sql;
     EXECUTE stalter;
	   deallocate  prepare  stalter;
		
	  set @parentsql=concat('select if(count(producttoolfieldid)>0 ,producttoolfieldid,0)  into @parentid from ld_producttoolfield where tabid=',ttabid,' and columnname="tax_amount" and tablename like "%detail"');
		
	  PREPARE stalter from @parentsql;
	  EXECUTE stalter;
		DEALLOCATE PREPARE stalter;
		
		set  @discountamountfieldid=0;
