DELIMITER ;;
CREATE  PROCEDURE `task_account100`(
)
BEGIN
     declare tmp_accountid  int default 0;
     declare tmp_accountname varchar(200) default '';
     declare tmp_smownerid  int default 0;
		 declare tmp_allocatedate date default NULL;
     declare mycursor cursor for select accountid from ld_salesorder where  TIMESTAMPDIFF(DAY,signed_data,CURDATE())<=90;
     DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
     open mycursor;
		 fetch mycursor into tmp_accountid;
				while(tmp_accountid is not null) DO
				update ld_account set publicaccount=0 where accountid=tmp_accountid;
							
				fetch mycursor into tmp_accountid;
				end while;
     close mycursor;
END ;;
DELIMITER ;
