CREATE  PROCEDURE `task_accout90`(
)
BEGIN
     declare tmp_accountid  int default 0;
     declare tmp_accountname varchar(200) default '';
     declare tmp_smownerid  int default 0;
		 declare tmp_lastorderdate date default NULL;
     declare mycursor cursor for select accountid, accountname,smownerid,lastorderdate from ld_account where publicaccount in (0,2,3) and TIMESTAMPDIFF(DAY,lastorderdate,CURDATE())>90;
     DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
     open mycursor;
		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_lastorderdate;
				while(tmp_accountid is not null) DO
						select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_lastorderdate and DATE_ADD(tmp_lastorderdate,INTERVAL 90 day));
								IF @cn1<1 then 
										update ld_account set publicaccount=1,protectdate=NULL,completed=NULL where accountid=tmp_accountid;
										set @maxid=0;
										select max(crmid) into @maxid from ld_crmentity;
										insert into ld_crmentity(crmid,setype)
										select @maxid+1,'Reminds';
										
										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
										select @maxid+1,concat('成交90天无联系记录客户：',tmp_accountname,'已自动转公海！'),now(),tmp_smownerid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;
									 
										insert into ld_logpublicaccount(username,operation,opdate,accountid)
										select '系统管理员','成交90天无联系记录客户',NOW(),tmp_accountid;
								END IF; 
				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid,tmp_lastorderdate;
				end while;
     close mycursor;
END ;;
