CREATE  PROCEDURE `task_accoutreminds10`(
)
BEGIN
     declare tmp_accountid  int default 0;
     declare tmp_accountname varchar(200) default '';
     declare tmp_smownerid  int default 0;
		 declare tmp_allocatedate date default NULL;
     declare mycursor cursor for select accountid, accountname,smownerid from ld_account where publicaccount in (2,3) and (TIMESTAMPDIFF(DAY,allocatedate,CURDATE())<10 and TIMESTAMPDIFF(DAY,allocatedate,CURDATE())>=7) and lastcontactdate<allocatedate;
     
		 DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
     open mycursor;
		 fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;
				while(tmp_accountid is not null) DO
						select count(1) into @cn1 from ld_contactrecords where accountid=tmp_accountid and (contactDate between tmp_lastorderdate and DATE_ADD(tmp_lastorderdate,INTERVAL 90 day));
										set @maxid=0;
										select max(crmid) into @maxid from ld_crmentity;
										insert into ld_crmentity(crmid,setype)
										select @maxid+1,'Reminds';
										
										insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
										select @maxid+1,concat('客户：',tmp_accountname,'领取7天后仍无联系记录，请尽快创建否则将自动转公海！'),now(),tmp_smownerid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;
									 
				fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;
				end while;
     close mycursor;
END ;;
